/usr/bin/bash -lc "/opt/conda/bin/python3 - <<'PY'
from pathlib import Path

# Verified peptides from the four PepQuery2 psm_rank outputs.
verified = set()
for f in sorted(Path('run_trace/extracted').glob('*_psm_rank.txt')):
    lines = f.read_text().splitlines()
    if not lines:
        continue
    header = lines[0].split('\\t')
    ci = header.index('confident')
    pi = header.index('peptide')
    for line in lines[1:]:
        parts = line.split('\\t')
        if len(parts) > max(ci, pi) and parts[ci] == 'Yes':
            verified.add(parts[pi])

# SGPS: leading empty col 1, Protein(s) col 2, Sequence col 6.
sgps = {}
for line in Path('data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular').read_text().splitlines()[1:]:
    parts = line.split('\\t')
    if len(parts) >= 6:
        seq = parts[5].strip()
        for pid in parts[1].split(';'):
            pid = pid.strip()
            if pid:
                sgps.setdefault(seq, set()).add(pid)

# MaxQuant: Sequence col 1, Proteins col 35 (0-based 34).
mq = {}
for i, line in enumerate(Path('data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular').read_text().splitlines()):
    if i == 0:
        continue
    parts = line.split('\\t')
    if len(parts) < 35:
        continue
    seq = parts[0].strip()
    for pid in parts[34].split(';'):
        pid = pid.strip()
        if pid:
            mq.setdefault(seq, set()).add(pid)

pairs = set()
for seq in verified:
    ids = set(sgps.get(seq, set())) | set(mq.get(seq, set()))
    for pid in ids:
        pairs.add((seq, pid))

# Sanity: every verified peptide has at least one assignment.
missing = [s for s in sorted(verified) if not (sgps.get(s) or mq.get(s))]
if missing:
    raise SystemExit(f'Missing peptide assignments: {missing}')

out = Path('final_answer/verified_peptides.tsv')
out.parent.mkdir(parents=True, exist_ok=True)
with out.open('w') as fh:
    fh.write('peptide\\tprotein_id\\n')
    for seq, pid in sorted(pairs):
        assert '\\t' not in seq and '\\t' not in pid
        fh.write(f'{seq}\\t{pid}\\n')

print(f'wrote {out} with {len(pairs)} rows and {len(verified)} verified peptides')
print(out.read_text().splitlines()[:8])
PY
